package HTTP::API::Core::RateLimit;use strict;use warnings;use Time::HiRes qw(time);sub new{my($c,%a)=@_;bless{map{$_=>$a{$_}}qw(limit remaining used reset reset_epoch retry_after resource source)},$c}sub from_headers{my($c,$h)=@_;$h||={};my%l=map{lc($_)=>$h->{$_}}keys%$h;my$s=exists$l{'ratelimit-limit'}||exists$l{'ratelimit-remaining'}||exists$l{'ratelimit-reset'}?'ratelimit':exists$l{'x-ratelimit-limit'}||exists$l{'x-ratelimit-remaining'}||exists$l{'x-ratelimit-reset'}?'x-ratelimit':undef;$c->new(limit=>_number($l{'ratelimit-limit'}//$l{'x-ratelimit-limit'}),remaining=>_number($l{'ratelimit-remaining'}//$l{'x-ratelimit-remaining'}),used=>_number($l{'ratelimit-used'}//$l{'x-ratelimit-used'}),reset=>_number($l{'ratelimit-reset'}),reset_epoch=>_number($l{'x-ratelimit-reset'}),retry_after=>_number($l{'retry-after'}),resource=>$l{'ratelimit-resource'}//$l{'x-ratelimit-resource'},source=>$s)}sub limit{$_[0]{limit}}sub remaining{$_[0]{remaining}}sub used{$_[0]{used}}sub reset{$_[0]{reset}}sub reset_epoch{$_[0]{reset_epoch}}sub retry_after{$_[0]{retry_after}}sub resource{$_[0]{resource}}sub source{$_[0]{source}}sub exhausted{defined($_[0]{remaining})&&$_[0]{remaining}<=0?1:0}sub wait_seconds{my($s,%a)=@_;my$n=exists$a{now}?$a{now}:time;return$s->{retry_after} if defined$s->{retry_after};return$s->{reset} if defined$s->{reset};if(defined$s->{reset_epoch}){my$w=$s->{reset_epoch}-$n;return$w>0?$w:0}undef}sub as_hash{my($s)=@_;+{map{$_=>$s->{$_}}qw(limit remaining used reset reset_epoch retry_after resource source)}}sub _number{my($v)=@_;return undef if !defined($v)||$v!~/\A(?:\d+(?:\.\d*)?|\.\d+)\z/;0+$v}1;
